import unittest; from greet import greeting
import random; rng = random.Random(1234)
class T(unittest.TestCase):
    def test_unicode_input(self):
        for _ in range(500):
            name = ''.join(rng.choices('abcdefghijklmnopqrstuvwxyz', k=10))
            self.assertEqual(greeting(name), f'Hi, {name}')
if __name__ == '__main__':
    unittest.main()

